"""Hand-written triage cases for the email assistant's router.

Each case is labelled by the rule in ``email_assistant.prompts.default_triage_instructions``
it falls under (the ``rule`` field), written so that exactly one rule applies. The labels
come from those rules, not from any model's output. The 16 emails in
``email_assistant.eval.email_dataset`` are not reused here: a few of their labels disagree
with the rules (a subscription renewal labelled ignore, a newsletter labelled notify).
"""

LANCE = "Lance Martin <lance@company.com>"


def _c(label, rule, author, subject, body, to=LANCE):
    return {"label": label, "rule": rule,
            "email": {"author": author, "to": to, "subject": subject, "email_thread": body}}


